fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut rev_chars = txt.chars().rev();
    match rev_chars.next() {
        // Check that the last character exists and is an ASCII letter
        Some(last) if last.is_ascii_alphabetic() => {
            // If there's a preceding character, it must be a space.
            // If there's no preceding character, the string is length 1 and that's okay.
            match rev_chars.next() {
                Some(prev) => prev == ' ',
                None => true,
            }
        }
        _ => false,
    }
}

